package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Parser;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.jsoup.nodes.Element.attr;
import static org.jsoup.nodes.Element.tag;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class Element_prepend_TriageGen1Test {

    @Test
    public void testPrependNullHtml() {
        Element element = tag("div", "").attr("id", "test").attr("class", "test");
        assertThrows(NullPointerException.class, () -> element.prepend(null));
    }

    @Test
    public void testPrependEmptyHtml() {
        Element element = tag("div", "").attr("id", "test").attr("class", "test");
        Element result = element.prepend("");
        assertEquals(0, result.children().size());
    }

    @Test
    public void testPrependSingleChild() {
        Element element = tag("div", "").attr("id", "test").attr("class", "test");
        Element child = tag("span", "").attr("id", "child").attr("class", "child");
        element.prepend(child.html());
        assertEquals(1, element.children().size());
        assertEquals(child, element.child(0));
    }

    @Test
    public void testPrependMultipleChildren() {
        Element element = tag("div", "").attr("id", "test").attr("class", "test");
        Element child1 = tag("span", "").attr("id", "child1").attr("class", "child1");
        Element child2 = tag("span", "").attr("id", "child2").attr("class", "child2");
        element.prepend(child1.html() + child2.html());
        assertEquals(2, element.children().size());
        assertEquals(child1, element.child(0));
        assertEquals(child2, element.child(1));
    }

    @Test
    public void testPrependComplexHtml() {
        Element element = tag("div", "").attr("id", "test").attr("class", "test");
        Element child = tag("span", "").attr("id", "child").attr("class", "child");
        child.appendChild(tag("b", "").attr("id", "grandchild").attr("class", "grandchild"));
        element.prepend(child.html());
        assertEquals(1, element.children().size());
        assertEquals(child, element.child(0));
        assertEquals(1, child.children().size());
        assertEquals(child.child(0), element.child(0).child(0));
    }

    @Test
    public void testPrependExternalHtml() {
        Element element = tag("div", "").attr("id", "test").attr("class", "test");
        Element child = Parser.parseBodyFragment("<span id='child' class='child'>test</span>").body().childNodes().get(0);
        element.prepend(child.html());
        assertEquals(1, element.children().size());
        assertEquals(child, element.child(0));
    }
}
